<?php
use EIPSI\ExternalApi as A;
d2_case('Cross-study grant and scientific sentinels remain isolated',function(){ $other=d2_publish();d2_finish($other,'OTHER_STUDY_SECRET');$k=d2_key();d2_error(function()use($k,$other){d2_read($k,array(),$other);},404,'eipsi_external_study_unavailable');d2_assert(strpos(json_encode(d2_read($k)),'OTHER_STUDY_SECRET')===false);});
d2_case('Data pages use stable row positions without duplicates',function(){ $p=$GLOBALS['nativeComplete']['p'];$k=d2_key(array($p['definition']['study']['logical_id']));$all=array();$cursor=null;do{$f=array('limit'=>2);if($cursor!==null)$f['cursor']=$cursor;$page=d2_read($k,$f,$p);$all=array_merge($all,$page['items']);$cursor=$page['next_cursor'];}while($cursor!==null);d2_assert(count($all)===count(d2_read($k,array(),$p)['items']));$ids=array_map(static function($r){return$r['participation_id'].'|'.$r['attempt_id'].'|'.$r['response_key'];},$all);d2_assert(count($ids)===count(array_unique($ids)));});
d2_case('Data cursor cannot cross key Study filters or discovery audience',function(){ $p=$GLOBALS['nativeComplete']['p'];$id=$p['definition']['study']['logical_id'];$k=d2_key(array($id,$GLOBALS['p']['definition']['study']['logical_id']));$cursor=d2_read($k,array('limit'=>1),$p)['next_cursor'];foreach(array(array(d2_key(array($id)),$p,array()),array($k,$GLOBALS['p'],array()),array($k,$p,array('include_partials'=>'true')))as$x)d2_error(function()use($x,$cursor){d2_read($x[0],array_merge(array('cursor'=>$cursor),$x[2]),$x[1]);},400,'eipsi_external_invalid_cursor');$d=(new A\Cursor())->encode($k['key']['id'],'STUDY_A','STUDY_Z');d2_error(function()use($k,$p,$d){d2_read($k,array('cursor'=>$d),$p);},400,'eipsi_external_invalid_cursor');});
d2_case('Malformed tampered and expired dataset cursors fail consistently',function(){ $p=$GLOBALS['nativeComplete']['p'];$k=d2_key(array($p['definition']['study']['logical_id']));$cursor=d2_read($k,array('limit'=>1),$p)['next_cursor'];foreach(array('', 'bad',substr($cursor,0,20).'!'.substr($cursor,21),$cursor.'x')as$c)d2_error(function()use($k,$p,$c){d2_read($k,array('cursor'=>$c),$p);},400,'eipsi_external_invalid_cursor');d2_error(function()use($k,$p,$cursor){(new A\StudyDataExport(static function(){return time()+3601;}))->read($k['principal'],$p['public'],array('cursor'=>$cursor));},400,'eipsi_external_invalid_cursor');});
foreach(array('revoke','scope','grant')as$change)d2_case('Current authorization is revalidated between pages: '.$change,function()use($change,$keys){$p=$GLOBALS['nativeComplete']['p'];$id=$p['definition']['study']['logical_id'];$k=d2_key(array($id));$cursor=d2_read($k,array('limit'=>1),$p)['next_cursor'];if($change==='revoke')$keys->revoke($k['key']['id'],1,1,A\Authenticator::requestId());else$keys->update($k['key']['id'],1,array('name'=>'Changed','scopes'=>array($change==='scope'?'read:studies':'read:data'),'grant_mode'=>$change==='grant'?'NONE':'SELECTED','studies'=>$change==='grant'?array():array($id),'expires_at'=>null),1,A\Authenticator::requestId());d2_error(function()use($k,$p,$cursor){d2_read($k,array('cursor'=>$cursor),$p);},$change==='revoke'?401:($change==='scope'?403:404),$change==='revoke'?'eipsi_external_unauthorized':($change==='scope'?'eipsi_external_scope_denied':'eipsi_external_study_unavailable'));});
d2_case('Privacy is rechecked between pages and already delivered bytes cannot be recalled',function(){ $p=d2_publish(true);$a=d2_finish($p,'A_BEFORE_PRIVACY');$b=d2_finish($p,'B_STILL_ALLOWED');$k=d2_key(array($p['definition']['study']['logical_id']));$page=d2_read($k,array('limit'=>1),$p);d2_withdraw($a['frame'],'DO_NOT_USE');$after=d2_read($k,array('cursor'=>$page['next_cursor']),$p);foreach($after['items']as$r)d2_assert($r['participation_id']!==$a['frame']['access']['execution_id']);$new=d2_read($k,array(),$p);d2_assert(count($new['items'])===1&&$new['items'][0]['value']==='B_STILL_ALLOWED');});
d2_case('Hard-deleted Study and its inert grant never return a ghost dataset',function()use($builder){$p=d2_publish();d2_finish($p);$id=$p['definition']['study']['logical_id'];$k=d2_key(array($id));$builder->deleteStudy($id,'ELIMINAR '.$id);d2_error(function()use($k,$p){d2_read($k,array(),$p);},404,'eipsi_external_study_unavailable');});
d2_case('Data and dictionary exclude contact identity process fields and private metadata',function(){ $p=d2_publish(true);$f=d2_finish($p,'SCIENTIFIC_ONLY');$k=d2_key(array($p['definition']['study']['logical_id']));$json=json_encode(array(d2_read($k,array(),$p),d2_read($k,array(),$p,true)));$participant=pf_participant($f['frame']);d2_assert(strpos($json,$participant['email'])===false);foreach(array('archived_email','verification_state','metadata_json','checkpoint_json','token','seed','device','trajectory')as$x)d2_assert(strpos($json,$x)===false);});
d2_case('Data audit contains counts bytes duration and a safe Study reference only',function()use($store){$k=d2_key();d2_read($k);d2_read($k,array('format'=>'csv'));d2_read($k,array(),null,true);$rows=$store->rows($store->prepare('SELECT event,details_json FROM '.$store->table('audit')." WHERE key_id=%s AND event IN ('DATA_JSON_OK','DATA_CSV_OK','DICTIONARY_OK')",$k['key']['id']));d2_assert(count($rows)===3);foreach($rows as$r){$d=json_decode($r['details_json'],true);d2_assert(isset($d['bytes'],$d['returned_count'],$d['duration_ms'],$d['study_ref']));d2_assert(strpos($r['details_json'],'SUM(')===false&&strpos($r['details_json'],'@')===false);}});
d2_case('Separate data budget does not consume discovery and bulk is stricter',function(){ $k=d2_key(null,array('read:data','read:studies'));for($i=0;$i<30;$i++)d2_read($k);try{d2_read($k);throw new RuntimeException('No rate rejection');}catch(EIPSI_Rate_Limit_Exception$e){d2_assert($e->getCode()===429);}$d=(new A\StudyDiscoveryQuery())->page($k['principal']);d2_assert(count($d['items'])===1);$csv=d2_key();for($i=0;$i<5;$i++)d2_read($csv,array('format'=>'csv'));try{d2_read($csv,array('format'=>'csv'));throw new RuntimeException('No CSV rejection');}catch(EIPSI_Rate_Limit_Exception$e){d2_assert($e->getCode()===429);}});
d2_case('HTTP unknown filters and format never leak paths SQL or payload',function(){foreach(array(array('format'=>'xlsx'),array('include_excluded'=>'true'),array('include_partials'=>'yes'),array('limit'=>1001))as$f){$r=d2_http(d2_key(),null,$f);d2_assert($r['status']===400);foreach(array('/var/www','SELECT ','SUM(')as$x)d2_assert(strpos($r['body'],$x)===false);}});
d2_case('Disabled API rejects data dictionary and a previously authenticated principal',function()use($store){$k=d2_key();$store->setEnabled(false,1,A\Authenticator::requestId(),time());try{foreach(array(false,true)as$d)d2_assert(d2_http(null,null,array(),$d)['status']===404);d2_error(function()use($k){d2_read($k);},404,'eipsi_external_unavailable');}finally{$store->setEnabled(true,1,A\Authenticator::requestId(),time());}});
d2_case('ALL data grant explicitly authorizes a future Study without a discovery scope',function(){$k=d2_key(array(),array('read:data'),'ALL');$p=d2_publish();d2_finish($p,'FUTURE_STUDY_ALLOWED');$r=d2_read($k,array(),$p);d2_assert(count($r['items'])===1&&$r['items'][0]['value']==='FUTURE_STUDY_ALLOWED');});
d2_case('HTTP Native data and dictionary load their read dependencies without an admin session',function(){ $p=$GLOBALS['nativeComplete']['p'];$k=d2_key(array($p['definition']['study']['logical_id']));foreach(array(false,true)as$dictionary){$r=d2_http($k,$p,array(),$dictionary);d2_assert($r['status']===200,'Native HTTP returned '.$r['status']);d2_assert(count($r['data']['items'])>=7);}});
